<?php $settings = receipt_settings(); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><title><?= e($invoice['invoice_no']) ?> | Deshappriya Motors</title><link rel="stylesheet" href="assets/css/invoice-thermal.css?v=<?= (int)filemtime(__DIR__.'/../assets/css/invoice-thermal.css') ?>"></head><body><article class="thermal-invoice"><header><strong><?= e($settings['garage_name']??'DESHAPRIYA MOTORS') ?></strong><span><?= e($settings['tagline']??'Garage Management System') ?></span><span><?= e($settings['address']??'') ?></span><span>Tel: <?= e($settings['contact_number']??'') ?></span></header><h1>INVOICE / PAYMENT RECEIPT</h1><div class="thermal-meta"><div><span>Invoice</span><b><?= e($invoice['invoice_no']) ?></b></div><div><span>Date</span><b><?= e(date('d M Y h:i A',strtotime($invoice['created_at']))) ?></b></div><?php if($invoice['job_card_no']): ?><div><span>Job Card</span><b><?= e($invoice['job_card_no']) ?></b></div><?php endif; ?><div><span>Customer</span><b><?= e($invoice['customer_name']?:'Walk-in Customer') ?></b></div><div><span>Phone</span><b><?= e($invoice['contact_number']?:'-') ?></b></div><div><span>Vehicle</span><b><?= e($invoice['vehicle_number']?:'-') ?></b></div></div><table><thead><tr><th>Description</th><th>Qty</th><th>Amount</th></tr></thead><tbody><?php foreach($invoice['items'] as $item): ?><tr><td><?= e($item['description']) ?><small><?= e(ucwords(str_replace('_',' ',$item['item_type']))) ?></small></td><td><?= number_format((float)$item['quantity'],2) ?></td><td><?= number_format((float)$item['line_total'],2) ?></td></tr><?php endforeach; ?></tbody></table><section class="totals"><div><span>Subtotal</span><b>Rs. <?= number_format((float)$invoice['subtotal'],2) ?></b></div><div><span>Special Service Charge</span><b>Rs. <?= number_format((float)$invoice['special_service_charge'],2) ?></b></div><div><span>Discount</span><b>- Rs. <?= number_format((float)$invoice['discount_amount'],2) ?></b></div><div class="grand"><span>TOTAL</span><b>Rs. <?= number_format((float)$invoice['total_amount'],2) ?></b></div></section><section class="payment"><div><span>Payment Method</span><b><?= e(ucfirst($invoice['payment_method']?:'-')) ?></b></div><div><span>Amount Applied</span><b>Rs. <?= number_format((float)$invoice['paid_amount'],2) ?></b></div><div><span>Remaining Due</span><b>Rs. <?= number_format((float)$invoice['balance_amount'],2) ?></b></div></section><footer><?= nl2br(e($settings['receipt_footer']??'Thank you for choosing Deshappriya Motors.')) ?></footer></article><div class="thermal-actions"><button onclick="window.print()">Print Receipt</button><a href="index.php?page=admin&amp;section=invoices-view&amp;id=<?= (int)$invoice['id'] ?>">Back to Invoice</a></div></body></html>
